const D = { energy:.4, n:.6, hue:30, glow:.7, sway:.5, riseR:.5, y:.6, x:.5, scale:1, speed:1, density:.5, style:'festival', seed:0, alpha:95 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const W=width,H=height,t=K.t,en=P.energy,sty=P.style,dc=drawingContext,TAU=Math.PI*2;
const N=Math.floor(5+P.n*22);
function lHue(i){ if(sty==='multi') return [0,30,50,330,190][i%5]; if(sty==='ghost') return 190+fr(i)*30; if(sty==='rose') return 330+fr(i)*20; if(sty==='gold') return 42; return P.hue+fr(i)*18; }
dc.save(); blendMode(ADD);
for(let i=0;i<N;i++){
  const dp=fr(i);   // depth
  const rise=(0.02+dp*0.05)*(0.4+en)*P.speed*(0.5+P.riseR);
  const yy=H*1.1-((fr(i+3)+t*rise)%1.25)*H*1.25;
  const xx=fr(i)*W + Math.sin(t*(0.3+dp*0.4)+i)*40*P.sway + Math.sin(t*0.13+i*2)*20;
  const sz=(10+dp*dp*30)*(0.6+P.scale*0.5);
  const h=lHue(i);
  const fl=0.75+0.25*Math.sin(t*(2+fr(i)*3)+i*2);
  // glow
  dc.shadowBlur=(14+sz*0.8)*P.glow*fl; dc.shadowColor=color(h,70,100).toString();
  // paper body (tapered cylinder)
  fill(color(h,55,95,(55+fl*35)*P.alpha/100)); noStroke();
  beginShape(); vertex(xx-sz*0.45,yy-sz*0.6); bezierVertex(xx-sz*0.62,yy, xx-sz*0.42,yy+sz*0.55, xx-sz*0.3,yy+sz*0.6);
  vertex(xx+sz*0.3,yy+sz*0.6); bezierVertex(xx+sz*0.42,yy+sz*0.55, xx+sz*0.62,yy, xx+sz*0.45,yy-sz*0.6); endShape(CLOSE);
  // inner flame core
  fill(color(45,60,100,(50+fl*40)*P.alpha/100)); ellipse(xx,yy+sz*0.18,sz*0.4,sz*0.5);
  // rim + opening
  dc.shadowBlur=0;
  fill(color(h,70,60,60*P.alpha/100)); rect(xx-sz*0.45,yy-sz*0.66,sz*0.9,sz*0.1,2);
  // reflection streak below (if low)
  if(yy>H*0.75){ fill(color(h,50,90,14*P.alpha/100)); ellipse(xx,H-(yy-H*0.75)*0.4, sz*0.8, sz*0.2); }
}
dc.restore(); blendMode(BLEND);
